//! 2D frequency counts and binning against Origin's `twoDBinning` (worksheet output).
//!
//! Reference scripts in `tools/origin-ref/stats4/` (`g3.py`, `g4.py`, `g5.py`); the inputs and Origin's numbers
//! are in `fixtures/bin2d_origin.rs`, made by `make-fixture3.py`. All inputs were generated by us. Bin edges, row
//! labels and the range comments of the columns agree exactly; the cell values to 1e-9.
//!
//! With only a number of intervals and no range, Origin picks a "nice" range by a rule we did not find; ours
//! matches 6 of the 8 measured axes and the 3 of 4 with one limit given. The axes that differ are listed in
//! `KNOWN_MISSES` and skipped (statistics.md 13).

#[path = "fixtures/bin2d_origin.rs"]
mod fixtures;

use fixtures::*;
use sheaf_calc::{AxisBins, Bin2dOptions, Bin2dStat, BinSize, bin2d};

/// (case, axis) pairs where our automatic range for a number of intervals differs from Origin's.
const KNOWN_MISSES: &[(&str, char)] = &[("i_auto5", 'y'), ("i_auto_x1", 'x'), ("i_max", 'x')];

fn axis(a: &Axis) -> AxisBins {
    AxisBins {
        min: a.min,
        max: a.max,
        size: match (a.inc, a.intervals) {
            (Some(w), _) => BinSize::Width(w),
            (None, Some(n)) => BinSize::Count(n),
            (None, None) => BinSize::Auto,
        },
        centers: a.centers,
        below: a.below,
        above: a.above,
    }
}

fn same(a: f64, b: f64) -> bool {
    (a.is_nan() && b.is_nan()) || (a - b).abs() <= 1e-9 * b.abs().max(1.0)
}

#[test]
fn twod_binning_matches_origin() {
    let mut checked = 0;
    for c in BIN2D_CASES {
        let opts = Bin2dOptions {
            x: axis(&c.x_axis),
            y: axis(&c.y_axis),
            stat: Bin2dStat::from_code(c.stat).unwrap_or_else(|| panic!("{}: stat {}", c.name, c.stat)),
        };
        let r = bin2d(c.x, c.y, &opts).unwrap_or_else(|| panic!("{}: no result", c.name));
        let miss_x = KNOWN_MISSES.contains(&(c.name, 'x'));
        let miss_y = KNOWN_MISSES.contains(&(c.name, 'y'));
        if !miss_x {
            let labels: Vec<f64> = (0..r.x.bins.len()).map(|i| r.x.label(i)).collect();
            assert_eq!(labels.len(), c.row_labels.len(), "{}: X bins {labels:?} vs {:?}", c.name, c.row_labels);
            for (a, b) in labels.iter().zip(c.row_labels) {
                assert!(same(*a, *b), "{}: X labels {labels:?} vs {:?}", c.name, c.row_labels);
            }
        }
        if !miss_y {
            assert_eq!(r.y.bins.len(), c.y_bins, "{}: Y bins", c.name);
            for (j, want) in c.comments.iter().enumerate() {
                assert_eq!(&r.y.range_text(j), want, "{}: comment of Y bin {j}", c.name);
            }
        }
        if !(miss_x || miss_y) {
            for (i, row) in c.cells.iter().enumerate() {
                for (j, want) in row.iter().enumerate() {
                    let got = r.cells[i][j];
                    assert!(same(got, *want), "{}: cell ({i}, {j}) {got} vs Origin {want}", c.name);
                }
            }
            checked += 1;
        }
    }
    assert_eq!(checked, BIN2D_CASES.len() - KNOWN_MISSES.len());
}

#[test]
fn the_known_misses_still_differ() {
    // If one of these starts to agree, take it off KNOWN_MISSES.
    for (name, ax) in KNOWN_MISSES {
        let c = BIN2D_CASES.iter().find(|c| c.name == *name).expect("case exists");
        let opts = Bin2dOptions { x: axis(&c.x_axis), y: axis(&c.y_axis), stat: Bin2dStat::Count };
        let r = bin2d(c.x, c.y, &opts).expect("result");
        let differs = match ax {
            'x' => {
                r.x.bins.len() != c.row_labels.len()
                    || (0..r.x.bins.len()).any(|i| !same(r.x.label(i), c.row_labels[i]))
            }
            _ => (0..c.comments.len()).any(|j| r.y.range_text(j) != c.comments[j]),
        };
        assert!(differs, "{name}: axis {ax} now agrees with Origin");
    }
}
